import{_ as a,o as t,c as r,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const f=JSON.parse('{"title":"Sanjeev AI Credits and Tiers","description":"Guide explaining the Basic and Pro tiers, as well as the Pay-As-You-Go Credit System and Overdraft feature.","frontmatter":{"title":"Sanjeev AI Credits and Tiers","description":"Guide explaining the Basic and Pro tiers, as well as the Pay-As-You-Go Credit System and Overdraft feature.","isInternal":false},"headers":[],"relativePath":"user_guides/credits_and_tiers.md","filePath":"user_guides/credits_and_tiers.md"}'),i={name:"user_guides/credits_and_tiers.md"};function n(o,e,d,u,l,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="sanjeev-ai-credits-and-tiers-guide" tabindex="-1">Sanjeev AI: Credits and Tiers Guide <a class="header-anchor" href="#sanjeev-ai-credits-and-tiers-guide" aria-label="Permalink to &quot;Sanjeev AI: Credits and Tiers Guide&quot;">​</a></h1><p>Welcome to Sanjeev AI! We&#39;ve updated our system to give you maximum flexibility and fairness.</p><h2 id="understanding-tiers" tabindex="-1">Understanding Tiers <a class="header-anchor" href="#understanding-tiers" aria-label="Permalink to &quot;Understanding Tiers&quot;">​</a></h2><p>Instead of a &quot;Free&quot; vs &quot;Paid&quot; model, Sanjeev AI uses <strong>Basic</strong> and <strong>Pro</strong> tiers to unlock features.</p><ul><li><strong>Basic Tier</strong>: Everyone gets access to the core Sanjeev AI experience, powered by high-speed AI models.</li><li><strong>Pro Tier</strong>: Upgrading unlocks advanced features, such as specialized autonomous agents, parallel workflows, and access to our most powerful reasoning models.</li></ul><h2 id="understanding-credits" tabindex="-1">Understanding Credits <a class="header-anchor" href="#understanding-credits" aria-label="Permalink to &quot;Understanding Credits&quot;">​</a></h2><p>Whether you are on the Basic or Pro tier, Sanjeev AI operates on a <strong>Pay-As-You-Go Credit System</strong>.</p><ul><li><strong>1 Token = 1 Credit</strong>: You only pay for exactly what the AI processes. There are no hidden subscription fees for usage!</li><li><strong>Top-Ups</strong>: You can purchase credits in bulk at any time through the Studio Dashboard.</li></ul><h3 id="the-overdraft-feature" tabindex="-1">The Overdraft Feature <a class="header-anchor" href="#the-overdraft-feature" aria-label="Permalink to &quot;The Overdraft Feature&quot;">​</a></h3><p>We know how frustrating it is when a complex AI task fails at 99% because you ran out of credits. To fix this, Sanjeev AI includes an <strong>Overdraft Buffer</strong>. If you run out of credits mid-generation, we will spot you the difference and allow your task to finish successfully! Your balance will simply show a negative number, and you will need to top up before starting a <em>new</em> task.</p>',10)])])}const g=a(i,[["render",n]]);export{f as __pageData,g as default};
